def _scan(text):
    """Split text on unquoted SEP. Each field is a list of (char, quoted) pairs.

    Quote characters are removed. Inside quotes, two QUOTE characters in a row
    give one QUOTE character.
    """
    fields, cur, quoted, i, n = [], [], False, 0, len(text)
    while i < n:
        ch = text[i]
        if ch == QUOTE:
            if quoted and i + 1 < n and text[i + 1] == QUOTE:
                cur.append((QUOTE, True))
                i += 2
                continue
            quoted = not quoted
        elif ch == SEP and not quoted:
            fields.append(cur)
            cur = []
        else:
            cur.append((ch, quoted))
        i += 1
    if quoted:
        raise ValueError(f"unclosed quote in {text!r}")
    fields.append(cur)
    return fields


def _text(chars):
    """Join chars, dropping unquoted whitespace at both ends."""
    lo, hi = 0, len(chars)
    while lo < hi and not chars[lo][1] and chars[lo][0].isspace():
        lo += 1
    while hi > lo and not chars[hi - 1][1] and chars[hi - 1][0].isspace():
        hi -= 1
    return "".join(c for c, _ in chars[lo:hi])


